resources.string:
// 寫入追蹤 ID，設定請求標頭，並組裝 JSON 請求體
pm.variables.set("traceId", Date.now());
pm.request.setHeader("X-Request-Id", pm.variables.get("traceId"));
pm.request.body.mode = "raw";
pm.request.body.json = { token: pm.variables.get("token") };

// 校驗狀態碼與耗時，並把 id 寫入環境
if (pm.response.statusCode !== 200) {
 throw new Error("expected 200, got " + pm.response.statusCode);
}
if (pm.response.time > 2000) {
 throw new Error("too slow: " + pm.response.time + "ms");
}
const body = pm.response.json();
if (body.id) pm.environment.set("userId", body.id);
pm.log("done in " + pm.response.time + "ms");
